1	# ---------------------------------------------------------------------------------------------------------------------
2	# REQUIRED PARAMETERS
3	# ---------------------------------------------------------------------------------------------------------------------
4	
5	variable "env" {
6	  description = "The environment (dev, staging, prod)"
7	  type        = string
8	  validation {
9	    condition     = var.env != null && var.env != ""
10	    error_message = "Env must be set"
11	  }
12	}
13	
14	variable "vpc_id" {
15	  description = "The ID of the VPC the RDS instance will be deployed into"
16	  type        = string
17	}
18	
19	variable "private_subnet_ids" {
20	  description = "List of private subnets in the VPC for the RDS Subnet Group"
21	  type        = list(string)
22	}
23	
24	variable "trusted_cidr_blocks" {
25	  description = "CIDR blocks allowed to access the RDS instance on port 5432"
26	  type        = list(string)
27	}
28	
29	variable "pg_version" {
30	  description = "Postgres database version prefix"
31	  type        = string
32	}
33	
34	# ---------------------------------------------------------------------------------------------------------------------
35	# OPTIONAL PARAMETERS
36	# ---------------------------------------------------------------------------------------------------------------------
37	
38	variable "name" {
39	  description = "The name of the RDS instance. Defaults to tools-database-<env>"
40	  type        = string
41	  default     = ""
42	}
43	
44	variable "db_name" {
45	  description = "Database name to create when creating the DB instance"
46	  type        = string
47	  default     = ""
48	}
49	
50	variable "admin_username" {
51	  description = "Database admin user"
52	  type        = string
53	  default     = "immuta_postgres"
54	}
55	
56	variable "rds_instance_size" {
57	  description = "RDS instance size"
58	  type        = string
59	  default     = "db.t4g.small"
60	}
61	
62	variable "allocated_storage" {
63	  description = "Initial storage allocated in GiB"
64	  type        = number
65	  default     = 20
66	}
67	
68	variable "max_allocated_storage" {
69	  description = "Upper limit for storage autoscaling in GiB"
70	  type        = number
71	  default     = 50
72	}
73	
74	variable "storage_encrypted" {
75	  description = "Whether to encrypt the RDS instance"
76	  type        = bool
77	  default     = true
78	}
79	
80	variable "storage_type" {
81	  description = "Storage type of the RDS instance"
82	  type        = string
83	  default     = "gp3"
84	}
85	
86	variable "encrypt_replicas" {
87	  description = "Whether to encrypt backup replicas"
88	  type        = bool
89	  default     = true
90	}
91	
92	variable "multi_az" {
93	  description = "Deploy the RDS instance as multi-AZ"
94	  type        = bool
95	  default     = false
96	}
97	
98	variable "final_snapshot" {
99	  description = "Take a final snapshot before destroying the DB instance"
100	  type        = bool
101	  default     = false
102	}
103	
104	variable "backup_retention_period" {
105	  description = "Days to retain backups (0-35)"
106	  type        = number
107	  default     = 21
108	}
109	
110	variable "replica_retention_period" {
111	  description = "Days to retain backup replicas (0-35)"
112	  type        = number
113	  default     = 21
114	}
115	
116	variable "enhanced_monitoring_enabled" {
117	  description = "Enable enhanced monitoring"
118	  type        = bool
119	  default     = true
120	}
121	
122	variable "performance_insights_enabled" {
123	  description = "Enable performance insights"
124	  type        = bool
125	  default     = true
126	}
127	
128	variable "kms_key_deletion_window_in_days" {
129	  description = "Days to retain KMS key after deletion"
130	  type        = number
131	  default     = 30
132	}
133	
134	variable "subnet_group_name_override" {
135	  description = "Override for subnet group name"
136	  type        = string
137	  default     = ""
138	}
139	
140	variable "dba_security_group_name_override" {
141	  description = "Override for external access SG name"
142	  type        = string
143	  default     = ""
144	}
145	
146	variable "security_group_name_override" {
147	  description = "Override for local access SG name"
148	  type        = string
149	  default     = ""
150	}
151	
152	variable "ca_cert_identifier" {
153	  description = "RDS CA cert identifier"
154	  type        = string
155	  default     = "rds-ca-rsa2048-g1"
156	}
157	
158	variable "parameters" {
159	  description = "A map of DB parameters to apply via a parameter group. If empty, the default parameter group is used"
160	  type        = set(map(string))
161	  default     = []
162	}
163	
164	variable "vault_secret_path" {
165	  description = "Vault KV path to store admin credentials"
166	  type        = string
167	  default     = "platform/tools-database"
168	}
169	
170	variable "tags" {
171	  description = "Tags to apply to created resources"
172	  type        = map(string)
173	  default     = {}
174	}
